private void buildChildren(
      Types.GroupBuilder builder,
      Iterator<SchemaElement> schema,
      int childrenCount,
      Iterator<ColumnOrder> columnOrders) {
    for (int i = 0; i < childrenCount; i++) {
      SchemaElement schemaElement = schema.next();

      // Create Parquet Type.
      Types.Builder childBuilder;
      if (schemaElement.type != null) {
        Types.PrimitiveBuilder primitiveBuilder = builder.primitive(
            getPrimitive(schemaElement.type), fromParquetRepetition(schemaElement.repetition_type));
        if (schemaElement.isSetType_length()) {
          primitiveBuilder.length(schemaElement.type_length);
        }
        if (schemaElement.isSetPrecision()) {
          primitiveBuilder.precision(schemaElement.precision);
        }
        if (schemaElement.isSetScale()) {
          primitiveBuilder.scale(schemaElement.scale);
        }
        if (columnOrders != null) {
          org.apache.parquet.schema.ColumnOrder columnOrder = fromParquetColumnOrder(columnOrders.next());
          // As per parquet format 2.4.0 no UNDEFINED order is supported. So, set undefined column order for
          // the types
          // where ordering is not supported.
          if (columnOrder.getColumnOrderName() == ColumnOrderName.TYPE_DEFINED_ORDER
              && (schemaElement.type == Type.INT96
                  || schemaElement.converted_type == ConvertedType.INTERVAL)) {
            columnOrder = org.apache.parquet.schema.ColumnOrder.undefined();
          }
          // INT96_TIMESTAMP_ORDER is only valid for INT96 columns, ignore it anywhere else.
          if (columnOrder.getColumnOrderName() == ColumnOrderName.INT96_TIMESTAMP_ORDER
              && schemaElement.type != Type.INT96) {
            columnOrder = org.apache.parquet.schema.ColumnOrder.undefined();
          }
          primitiveBuilder.columnOrder(columnOrder);
        } else if (schemaElement.type == Type.FLOAT
            || schemaElement.type == Type.DOUBLE
            || (schemaElement.isSetLogicalType() && schemaElement.logicalType.isSetFLOAT16())) {
          // A footer without column orders predates IEEE_754_TOTAL_ORDER, so a floating-point column
          // here must not inherit the (IEEE 754 total order) construction-time default: its stats, if
          // any, were written under the legacy type-defined order and must be read under it.
          primitiveBuilder.columnOrder(org.apache.parquet.schema.ColumnOrder.typeDefined());
        } else if (schemaElement.type == Type.INT96) {
          // A footer without column orders predates INT96_TIMESTAMP_ORDER, so an INT96 column here
          // must not inherit the (chronological) construction-time default: its stats, if any, were
          // written under the legacy order and must be ignored.
          primitiveBuilder.columnOrder(org.apache.parquet.schema.ColumnOrder.undefined());
        }
        // Gracefully handle unsupported logical type combinations on the read path.
        primitiveBuilder.ignoreUnsupportedLogicalAnnotations();
        childBuilder = primitiveBuilder;
      } else {
        childBuilder = builder.group(fromParquetRepetition(schemaElement.repetition_type));
        buildChildren((Types.GroupBuilder) childBuilder, schema, schemaElement.num_children, columnOrders);
      }

      if (schemaElement.isSetLogicalType()) {
        LogicalTypeAnnotation logicalTypeAnnotation = getLogicalTypeAnnotation(schemaElement.logicalType);
        if (logicalTypeAnnotation != null) {
          childBuilder.as(logicalTypeAnnotation);
        }
      }
      if (schemaElement.isSetConverted_type()) {
        OriginalType originalType = getLogicalTypeAnnotation(schemaElement.converted_type, schemaElement)
            .toOriginalType();
        OriginalType newOriginalType = (schemaElement.isSetLogicalType()
                && getLogicalTypeAnnotation(schemaElement.logicalType) != null)
            ? getLogicalTypeAnnotation(schemaElement.logicalType).toOriginalType()
            : null;
        if (!originalType.equals(newOriginalType)) {
          if (newOriginalType != null) {
            LOG.warn(
                "Converted type and logical type metadata mismatch (convertedType: {}, logical type: {}). Using value in converted type.",
                schemaElement.converted_type,
                schemaElement.logicalType);
          }
          childBuilder.as(originalType);
        }
      }
      if (schemaElement.isSetField_id()) {
        childBuilder.id(schemaElement.field_id);
      }

      childBuilder.named(schemaElement.name);
    }
  }

