        }
        String crs = params.isEmpty() ? null : params.get(0);
        return geometryType(crs);
      }
    },
    GEOGRAPHY {
      @Override
      protected LogicalTypeAnnotation fromString(List<String> params) {
        if (params.size() > 2) {
          throw new RuntimeException(
